/**
 * LM-410: product_inputs.forSecurity and ValuationRequests.typed.
 *
 * The shared cases live in test-fixtures/product-inputs/, one file per case,
 * generated by ledger-models-python/test/requests/test_product_input_builders.py
 * and read by the Java, Python and Rust tests too. The directory is listed at
 * run time. See docs/adr/product_input_builders.md.
 */
import * as fs from 'fs';
import * as path from 'path';
import * as jspb from 'google-protobuf';

import hierarchy from '../../../../hierarchy.json';
import { armFor, checkProductInput, forSecurity, MarketData } from './product_inputs';
import { ValuationRequests } from '../../requests/valuation/ValuationRequests';
import { MissingMarketDataError, ModelValidationError, UnmappedProductTypeError } from '../errors';
import { MeasureProto } from '../../../fintekkers/models/position/measure_pb';
import { PositionProto } from '../../../fintekkers/models/position/position_pb';
import { PriceProto } from '../../../fintekkers/models/price/price_pb';
import { SecurityProto } from '../../../fintekkers/models/security/security_pb';
import { LocalTimestampProto } from '../../../fintekkers/models/util/local_timestamp_pb';
import { ValuationRequestProto } from '../../../fintekkers/requests/valuation/valuation_request_pb';
import {
  BondInput, InflationIndexInput, ProductInput, ReferenceRateFixingProto, YieldCurveInput,
} from '../../../fintekkers/requests/valuation/product_inputs_pb';

const FIXTURES = path.resolve(__dirname, '../../../../../test-fixtures/product-inputs');

interface ErrorSpec { type: string; arm?: string; kind?: string; field?: string }
interface Fixture {
  name: string;
  security_hex: string;
  price_hex: string;
  market_data?: { cpi_hex?: string; fixings_hex?: string[]; curve_hex?: string };
  arm?: string;
  expected_hex?: string;
  error?: ErrorSpec;
  typed: { asof_hex: string; position_hex: string; measures: string[]; expected_hex?: string; product_input_hex?: string };
}

const cases: Fixture[] = fs.readdirSync(FIXTURES)
  .filter((f) => f.endsWith('.json'))
  .sort()
  .map((f) => ({ ...JSON.parse(fs.readFileSync(path.join(FIXTURES, f), 'utf-8')), name: f.replace(/\.json$/, '') }));
const success = cases.filter((c) => c.arm !== undefined);
const errors = cases.filter((c) => c.error !== undefined);
const fixture = (name: string): Fixture => cases.find((c) => c.name === name)!;

const bytes = (hex: string): Uint8Array => Uint8Array.from(Buffer.from(hex, 'hex'));
const hexOf = (m: jspb.Message): string => Buffer.from(m.serializeBinary()).toString('hex');

const security = (c: Fixture) => SecurityProto.deserializeBinary(bytes(c.security_hex));
const price = (c: Fixture) => PriceProto.deserializeBinary(bytes(c.price_hex));
function marketData(c: Fixture): MarketData {
  const md = c.market_data ?? {};
  return {
    cpi: md.cpi_hex ? InflationIndexInput.deserializeBinary(bytes(md.cpi_hex)) : undefined,
    fixings: (md.fixings_hex ?? []).map((h) => ReferenceRateFixingProto.deserializeBinary(bytes(h))),
    curve: md.curve_hex ? YieldCurveInput.deserializeBinary(bytes(md.curve_hex)) : undefined,
  };
}
function typedArgs(c: Fixture): [LocalTimestampProto, PositionProto, MeasureProto[]] {
  return [
    LocalTimestampProto.deserializeBinary(bytes(c.typed.asof_hex)),
    PositionProto.deserializeBinary(bytes(c.typed.position_hex)),
    c.typed.measures.map((m) => MeasureProto[m as keyof typeof MeasureProto]),
  ];
}

function caught(fn: () => unknown): Error {
  try {
    fn();
  } catch (e) {
    return e as Error;
  }
  throw new Error('expected a throw');
}

function expectError(e: Error, spec: ErrorSpec): void {
  expect(e.constructor.name).toBe(spec.type);
  if (spec.type === 'MissingMarketDataError') {
    const m = e as MissingMarketDataError;
    expect(m).toBeInstanceOf(MissingMarketDataError);
    expect([m.arm, m.kind, m.field]).toEqual([spec.arm, spec.kind, spec.field]);
    expect(m.message).toContain(spec.arm);
    expect(m.message).toContain(spec.kind);
  } else {
    expect(e).toBeInstanceOf(UnmappedProductTypeError);
  }
}

// ---- forSecurity

test('fixtures cover every arm in valuation_arms', () => {
  const entries = (hierarchy as unknown as { valuation_arms: { entries: { arm: string }[] } }).valuation_arms.entries;
  const arms = new Set(entries.map((e) => e.arm));
  expect(new Set(success.map((c) => c.arm))).toEqual(arms);
  expect(success).toHaveLength(arms.size);
});

test.each(success.map((c) => [c.name, c] as const))('%s: forSecurity matches the fixture bytes', (_name, c) => {
  expect(hexOf(forSecurity(security(c), price(c), marketData(c)))).toBe(c.expected_hex);
});

// R1: the arm is armFor's, and each field is the input it came from.
test.each(success.map((c) => [c.name, c] as const))('%s: forSecurity fields', (_name, c) => {
  const [s, p, md] = [security(c), price(c), marketData(c)];
  const out = forSecurity(s, p, md);
  expect(armFor(s)).toBe(c.arm);
  const body = {
    bond: out.getBond(), tips: out.getTips(), frn: out.getFrn(), mbs: out.getMbs(), equity: out.getEquity(), cash: out.getCash(),
  }[c.arm!]!;
  expect(body).toBeDefined();
  expect(hexOf(body.getSecurity()!)).toBe(hexOf(s));
  const fields = body as unknown as Record<string, unknown>;
  if (c.arm === 'equity' || c.arm === 'cash') {
    expect(hexOf((fields.getUnitPrice as () => jspb.Message).call(body))).toBe(hexOf(p.getPrice()!));
    expect(fields.getCleanPrice).toBeUndefined();
  } else {
    expect(hexOf((fields.getCleanPrice as () => jspb.Message).call(body))).toBe(hexOf(p.getPrice()!));
    expect(fields.getUnitPrice).toBeUndefined();
    expect((fields.hasCostBasis as () => boolean).call(body)).toBe(false);
  }
  if (c.arm === 'tips') expect(hexOf(out.getTips()!.getCpi()!)).toBe(hexOf(md.cpi!));
  if (c.arm === 'frn') {
    expect(out.getFrn()!.getFixingsList().map(hexOf)).toEqual(md.fixings!.map(hexOf));
    expect(hexOf(out.getFrn()!.getCurve()!)).toBe(hexOf(md.curve!));
  }
});

test.each(errors.map((c) => [c.name, c] as const))('%s: forSecurity throws the fixture error', (_name, c) => {
  expectError(caught(() => forSecurity(security(c), price(c), marketData(c))), c.error!);
});

test('forSecurity with no market data throws MissingMarketDataError(tips, CPI_U)', () => {
  const c = fixture('tips');
  for (const md of [undefined, null]) {
    const e = caught(() => forSecurity(security(c), price(c), md)) as MissingMarketDataError;
    expect(e).toBeInstanceOf(MissingMarketDataError);
    expect([e.arm, e.kind]).toEqual(['tips', 'CPI_U']);
  }
});

// ---- ValuationRequests.typed

test.each(success.map((c) => [c.name, c] as const))('%s: typed matches the fixture and sets only typed fields', (_name, c) => {
  const productInput = forSecurity(security(c), price(c), marketData(c));
  const [asof, position, measures] = typedArgs(c);
  const request = ValuationRequests.typed(asof, productInput, position, measures);
  // jspb writes fields in .proto declaration order (measures, 30, before
  // position_input, 21), the other bindings in field-number order. Both are
  // valid encodings of the same message, so compare the fixture re-encoded by
  // jspb. ProductInput's declaration order is its field order: its bytes match
  // the fixture as they are (test above).
  expect(hexOf(request)).toBe(hexOf(ValuationRequestProto.deserializeBinary(bytes(c.typed.expected_hex!))));
  expect(request.hasSecurityInput()).toBe(false);
  expect(request.hasPriceInput()).toBe(false);
  expect(request.hasPositionInput()).toBe(true);
  expect(request.getPositionInput()).toBe(position);
  expect(request.getProductInput()).toBe(productInput);
});

test.each(errors.map((c) => [c.name, c] as const))('%s: typed throws the fixture error', (_name, c) => {
  const productInput = ProductInput.deserializeBinary(bytes(c.typed.product_input_hex!));
  const [asof, position, measures] = typedArgs(c);
  expectError(caught(() => ValuationRequests.typed(asof, productInput, position, measures)), c.error!);
});

test('typed requires a position', () => {
  const c = fixture('bond');
  const [asof, , measures] = typedArgs(c);
  const e = caught(() => ValuationRequests.typed(asof, forSecurity(security(c), price(c)), undefined, measures));
  expect(e).toBeInstanceOf(ModelValidationError);
  expect((e as ModelValidationError).field).toBe('position_input');
});

test('typed rejects an arm armFor did not pick', () => {
  const c = fixture('tips');
  const wrong = new ProductInput().setBond(new BondInput().setSecurity(security(c)).setCleanPrice(price(c).getPrice()));
  const [asof, position, measures] = typedArgs(c);
  const e = caught(() => ValuationRequests.typed(asof, wrong, position, measures));
  expect(e).toBeInstanceOf(ModelValidationError);
  expect(e).not.toBeInstanceOf(MissingMarketDataError);
  expect((e as ModelValidationError).field).toBe('product_input.bond');
});

test('typed rejects an input with no arm', () => {
  const [asof, position, measures] = typedArgs(fixture('bond'));
  const e = caught(() => ValuationRequests.typed(asof, new ProductInput(), position, measures));
  expect((e as ModelValidationError).field).toBe('product_input');
  expect(() => checkProductInput(new ProductInput())).toThrow(ModelValidationError);
});
